@section('title','Latest Intelligence — '.config('platform.name'))
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const grid=document.querySelector('.latest-grid'),search=document.querySelector('.latest-search input');let timer;async function load(url){grid.textContent='Loading latest intelligence...';try{const r=await fetch(url,{headers:{Accept:'application/json'}}),data=await r.json();if(!r.ok)throw new Error();grid.innerHTML='';data.data.forEach(a=>{const card=document.createElement('article');card.className='latest-card';const tag=document.createElement('span');tag.className='latest-tag';tag.textContent=(a.category.icon||'')+' '+a.category.name;const h=document.createElement('h2');h.textContent=a.title;const p=document.createElement('p');p.textContent=a.excerpt||'';const link=document.createElement('a');link.className='latest-read';link.href='/latest/'+encodeURIComponent(a.slug);link.textContent='Read analysis →';card.append(tag,h,p,link);grid.append(card)});if(!data.data.length)grid.textContent='No matching intelligence.'}catch(e){grid.textContent='Unable to load intelligence. Please retry.'}}const filters=[...document.querySelectorAll('.latest-filter')];filters.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();filters.forEach(item=>{item.classList.remove('active');item.setAttribute('aria-pressed','false')});a.classList.add('active');a.setAttribute('aria-pressed','true');const u=new URL(a.href);history.replaceState({},'',u);load('{{route('news.ajax')}}?category='+encodeURIComponent(u.searchParams.get('category')||'')+'&search='+encodeURIComponent(search.value))}));search.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>load('{{route('news.ajax')}}?search='+encodeURIComponent(search.value)),300)});});</script>@endpush
@push('styles')<style>.latest-hero{padding:48px 0;background:linear-gradient(120deg,#0b1933,#234f83);color:#fff}.latest-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.latest-card{display:flex;flex-direction:column;padding:22px;border:1px solid #dbe5f1;border-radius:16px;background:#fff}.latest-card h2{font-size:20px}.latest-card p{color:#667085}.latest-tag{width:max-content;padding:6px 10px;border-radius:20px;background:#e8f2ff;color:#175ab8;font-size:12px;font-weight:800}.latest-meta{margin-top:auto;color:#748198;font-size:12px}.latest-read{margin-top:16px;color:#1769ff;font-weight:800;text-decoration:none}.latest-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:28px;align-items:start}.latest-sidebar{position:sticky;top:20px;padding:20px;border:1px solid #d9e7f7;border-radius:18px;background:rgba(255,255,255,.9);box-shadow:0 10px 30px rgba(31,78,140,.08)}.latest-sidebar-title{display:block;margin:0 0 14px;color:#0b2748;font-size:15px}.latest-filters{display:flex;gap:9px;flex-direction:column}.latest-filter{display:flex;align-items:center;justify-content:flex-start;width:100%;min-height:44px;padding:10px 17px;border:1px solid #c8d9ee;border-radius:12px;background:linear-gradient(180deg,#fff,#f5f9ff);color:#263b58!important;font-size:14px;font-weight:750;text-decoration:none!important;box-shadow:0 3px 9px rgba(31,78,140,.06);cursor:pointer;transition:transform .18s ease,border-color .18s ease,background .18s ease,box-shadow .18s ease}.latest-filter:hover{transform:translateY(-2px);border-color:#72a4e8;background:#edf5ff;color:#174f9d!important;box-shadow:0 8px 18px rgba(31,78,140,.14)}.latest-filter.active{border-color:#1769ff;background:linear-gradient(135deg,#1769ff,#3b82f6);color:#fff!important;box-shadow:0 8px 18px rgba(23,105,255,.25)}.latest-filter:focus-visible{outline:3px solid rgba(23,105,255,.25);outline-offset:3px}.latest-search{display:flex;gap:8px;margin-top:20px;max-width:650px}.latest-search input{flex:1;padding:12px;border:0;border-radius:9px}.latest-search button{padding:12px 18px;border:0;border-radius:9px;background:#1769ff;color:#fff}@media(max-width:1000px){.latest-layout{grid-template-columns:220px minmax(0,1fr)}.latest-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.latest-layout{display:block}.latest-sidebar{position:static;margin-bottom:26px}.latest-filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.latest-grid{grid-template-columns:1fr}}@media(max-width:460px){.latest-filters{grid-template-columns:1fr}}</style>@endpush
@section('content')<section class="latest-hero"><div class="container"><h1>Latest Intelligence</h1><p>Stay ahead of technology, industry, jobs and career trends.</p><form class="latest-search"><input name="search" value="{{request('search')}}" placeholder="Search latest intelligence..."><button>Search</button></form></div></section><section class="section"><div class="container latest-layout"><aside class="latest-sidebar"><strong class="latest-sidebar-title">Browse intelligence</strong><nav class="latest-filters" aria-label="Intelligence categories"><a class="latest-filter {{request('category')?'':'active'}}" aria-pressed="{{request('category')?'false':'true'}}" href="{{route('news.index')}}">All</a>@foreach($categories as $category)<a class="latest-filter {{request('category')===$category->slug?'active':''}}" aria-pressed="{{request('category')===$category->slug?'true':'false'}}" href="{{route('news.index',['category'=>$category->slug])}}">{{$category->icon}} {{$category->name}}</a>@endforeach</nav></aside><div class="latest-main">@include('news.partials.mechanical-industry')<div class="latest-grid">@forelse($articles as $article)<article class="latest-card"><span class="latest-tag">{{$article->category->icon}} {{$article->category->name}}</span><h2>{{$article->title}}</h2><p>{{$article->excerpt}}</p><div class="latest-meta">{{$article->source?->name??'Official source'}} · {{$article->published_at?->diffForHumans()}}</div><a class="latest-read" href="{{route('news.show',$article->slug)}}">Read analysis →</a></article>@empty<p>No published intelligence matches this filter.</p>@endforelse</div><div style="margin-top:28px">{{$articles->links()}}</div></div></div></section>@endsection
